import { icon } from './dashboard.mjs';
export const CURRENCIES={BTC:{name:'Bitcoin',icon:'btc',networks:['Bitcoin Network']},ETH:{name:'Ethereum',icon:'eth',networks:['Ethereum (ERC20)']},USDT:{name:'Tether',icon:null,networks:['Tron (TRC20)','Ethereum (ERC20)']},SOL:{name:'Solana',icon:'sol',networks:['Solana Network']}};
export const usd=cents=>'$'+(cents/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
export function currencyFields(prefix,currency='BTC',network){const c=CURRENCIES[currency];return '<div class="transfer-field"><label for="'+prefix+'-currency">'+(prefix==='deposit'?'Select Cryptocurrency':'Select Currency')+'</label><div class="currency-select">'+(c.icon?'<img src="/assets/'+c.icon+'@2x.png" alt="">':'<span class="tether-mark" aria-hidden="true">₮</span>')+'<select id="'+prefix+'-currency" name="currency">'+Object.entries(CURRENCIES).map(([s,c])=>'<option value="'+s+'" '+(s===currency?'selected':'')+'>'+s+'　'+c.name+'</option>').join('')+'</select></div></div><div class="transfer-field"><label for="'+prefix+'-network">Select Network</label><select id="'+prefix+'-network" name="network">'+c.networks.map(n=>'<option '+(n===network?'selected':'')+'>'+n+'</option>').join('')+'</select></div>';}
export function historyHTML(type){const label=type==='withdraw'?'Withdrawal':'Deposit';return '<section class="deposit-panel deposit-history" aria-labelledby="transfer-history-title"><h2 id="transfer-history-title"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 5v7l5 3"/></svg> '+label+' History</h2><div class="deposit-history-empty">'+icon(type)+'<p>No '+label.toLowerCase()+' history</p></div></section>';}
